mapper.select:
select from_poi_id, to_poi_id, transit_minutes, distance_m, created_at
from attraction_adjacency
where from_poi_id = #{fromPoiId}

select from_poi_id, to_poi_id, transit_minutes, distance_m, created_at
from attraction_adjacency
where to_poi_id = #{toPoiId}

select from_poi_id, to_poi_id, transit_minutes, distance_m, created_at
from attraction_adjacency
where from_poi_id = #{poiId} or to_poi_id = #{poiId}
